import { consumeSseEventBlocks, extractOpenAiStreamErrorMessage, extractOpenAiStreamTextDelta, extractSseEventData } from "../modules/chat/openAiStream.js";

/** Read an OpenAI-compatible SSE completion. Only visible content reaches
 * `onText`; separate reasoning fields are never mixed into story text. The
 * full content is returned so callers keep the exact generated bytes. */
export async function readOpenAiTextStream(response: Response, onText: (delta: string) => void, signal?: AbortSignal) {
  if (!response.body) throw new Error("Streaming response has no body");
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "", content = "";
  let usage: unknown;
  const handle = (events: string[]) => {
    for (const event of events) {
      const data = extractSseEventData(event);
      if (!data || data === "[DONE]") continue;
      let parsed: unknown;
      try { parsed = JSON.parse(data); } catch { continue; }
      const error = extractOpenAiStreamErrorMessage(parsed);
      if (error) throw new Error(error);
      const root = parsed as { usage?: unknown };
      if (root.usage) usage = root.usage;
      const delta = extractOpenAiStreamTextDelta(parsed);
      if (delta) { content += delta; onText(delta); }
    }
  };
  try {
    while (true) {
      signal?.throwIfAborted();
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      if (buffer.length > 4 * 1024 * 1024) throw new Error("Streaming response chunk is too large");
      const { events, rest } = consumeSseEventBlocks(buffer);
      buffer = rest;
      handle(events);
    }
    buffer += decoder.decode();
    handle(consumeSseEventBlocks(buffer, true).events);
  } finally {
    await reader.cancel().catch(() => undefined);
  }
  return { content, usage };
}
